   171	          return stream.anyMatch(element -> Boolean.TRUE.equals(ExpressionInterpreter.of(predicate).apply(element)));
   172	        } else if (op == IterableOperators.ALL) {
   173	          return stream.allMatch(element -> Boolean.TRUE.equals(ExpressionInterpreter.of(predicate).apply(element)));
   174	        }
   175	        return stream.noneMatch(element -> Boolean.TRUE.equals(ExpressionInterpreter.of(predicate).apply(element)));
   176	      }
   177	
   178	      if (op.arity() == Operator.Arity.BINARY) {
   179	        Preconditions.checkArgument(call.arguments().size() == 2, "Expected two arguments for %s got %s", call, call.arguments().size());
   180	        final Object left = call.arguments().get(0).accept(this);
   181	        if (left == UNKNOWN) {
   182	          return UNKNOWN;
   183	        }
   184	
   185	        final Object right = call.arguments().get(1).accept(this);
   186	        if (right == UNKNOWN) {
   187	          return UNKNOWN;
   188	        }
   189	
   190	        return binaryCall(call, left, right);
   100	
   101	    if (op == Operators.NOT) {
   102	      return this.negate(args.get(0));
   103	    }
   104	
   105	    if (op == IterableOperators.IS_EMPTY || op == IterableOperators.NOT_EMPTY) {
   106	      Preconditions.checkArgument(args.size() == 1, "Size should be 1 for %s but was %s", op, args.size());
   107	      final String field = fieldName(args.get(0));
   108	      return op == IterableOperators.IS_EMPTY ? Filters.eq(field, Collections.emptyList())
   109	              : Filters.and(Filters.exists(field), Filters.ne(field, null), Filters.ne(field, Collections.emptyList()));
   110	    }
   111	    
   112	    if (op == IterableOperators.ALL || op == IterableOperators.NONE ||
   113	        (op == IterableOperators.ANY && !isLegacyFlatAny(call))) {
   114	      return this.buildQuantifier(call);
   115	    }
   116	
   117	    if (op == IterableOperators.ANY) {
   118	      Call rightCall = call;
   119	      Path path = null;
   120	
   121	      while (rightCall.operator() == IterableOperators.ANY) {
   122	        Preconditions.checkArgument(rightCall.arguments().size() == 2, "Expected two arguments for %s got %s", rightCall, rightCall.arguments().size());
   123	        Preconditions.checkArgument(rightCall.arguments().get(0) instanceof Path, "%s is not a path", rightCall.arguments().get(0));
   124	        Preconditions.checkArgument(rightCall.arguments().get(1) instanceof Call, "%s is not a call", rightCall.arguments().get(1));
   125	
   126	        Path subPath = (Path) rightCall.arguments().get(0);
   127	        if (path != null) {
   128	          for (java.lang.reflect.Member member : subPath.members()) {
   129	            path = path.append(member);
   130	          }
   131	        } else {
   132	          path = subPath;
   133	        }
   134	        rightCall = (Call) rightCall.arguments().get(1);
   135	      }
   136	
   137	      // Handle AND/OR/NOT operators within ANY (for compound conditions on array elements).
   138	      // Also use $elemMatch for NOT_EQUAL and NOT_IN: flat dot-path $ne/$nin means "no element
   139	      // matches" (universal), but any().isNot/notIn requires existential ("at least one element").
   140	      if (rightCall.operator() == Operators.AND ||
   141	          rightCall.operator() == Operators.OR ||
   142	          rightCall.operator() == Operators.NOT ||
   143	          rightCall.operator() == Operators.NOT_EQUAL ||
   144	          rightCall.operator() == Operators.NOT_IN) {
   145	        final String arrayField = fieldName(path);
   146	        Bson condition = this.buildElemMatchCondition(rightCall);
   147	        return Filters.elemMatch(arrayField, condition);
   148	      }
   149	
   150	      // Handle simple comparison operators within ANY
   151	      Preconditions.checkArgument(rightCall.arguments().get(0) instanceof Path,"%s is not a path", rightCall.arguments().get(0));
   152	
   153	      // Reconstruct the full path by combining the array path with the condition path
   154	      Path currentPath = Visitors.toPath(rightCall.arguments().get(0));
   155	      List<Path> paths = new ArrayList<>();
   156	      while (currentPath.parent().isPresent()) {
   157	        paths.add(currentPath);
   158	        currentPath = currentPath.parent().get();
   159	      }
   160	      Collections.reverse(paths);
   161	      for (Path tmpPath : paths) {
   162	        path = Path.combine(path, tmpPath);
   163	      }
   164	
   165	      return this.buildCondition(rightCall, rightCall.operator(), path);
   166	    }
   167	
   168	    if (op.arity() == Operator.Arity.BINARY) {
   169	      return this.binaryCall(call);
   170	    }
   171	
   172	
   173	    throw new UnsupportedOperationException(String.format("Not yet supported (%s): %s", call.operator(), call));
   174	  }
   175	
   176	  private static boolean isLegacyFlatAny(Call call) {
   177	    if (!(call.arguments().get(1) instanceof Call)) {
   178	      return false;
   179	    }
   180	
   181	    Operator operator = ((Call) call.arguments().get(1)).operator();
   182	    return operator == Operators.EQUAL || operator == Operators.IN;
   183	  }
   184	
   185	  private Bson buildQuantifier(Call call) {
   186	    Preconditions.checkArgument(call.arguments().size() == 2, "Expected two arguments for %s got %s", call, call.arguments().size());
   187	    Preconditions.checkArgument(call.arguments().get(0) instanceof Path, "%s is not a path", call.arguments().get(0));
   188	    Preconditions.checkArgument(call.arguments().get(1) instanceof Call, "%s is not a call", call.arguments().get(1));
   189	
   190	    String field = fieldName(call.arguments().get(0));
   191	    BsonValue input = new BsonString("$" + field);
   192	    BsonValue expression = buildQuantifierExpression(call.operator(), input,
   193	        (Call) call.arguments().get(1), "element", true);
   194	    return Filters.and(arrayType(field), Filters.expr(expression));
   195	  }
   196	
   197	  private BsonValue buildQuantifierExpression(Operator operator, BsonValue input, Call predicate,
   198	      String variable, boolean expected) {
   199	    BsonValue safeInput = safeArray(input);
   200	    BsonValue elementPredicate = quantifiedExpression(predicate, "$$" + variable, true);
   201	    BsonDocument filter = new BsonDocument("input", safeInput)
   202	        .append("as", new BsonString(variable))
   203	        .append("cond", elementPredicate);
   204	    BsonValue count = expression("$size", new BsonDocument("$filter", filter));
   205	    BsonValue matches = expression("$gt", count, new BsonInt32(0));
   206	    if (operator == IterableOperators.ALL) {
   207	      matches = expression("$eq", count, expression("$size", safeInput));
   208	    } else if (operator == IterableOperators.NONE) {
   209	      matches = expression("$eq", count, new BsonInt32(0));
   210	    }
   211	    return expected ? matches : expression("$not", matches);
   212	  }
   213	
   214	  private BsonValue quantifiedExpression(Call call, String root, boolean expected) {
   215	    Operator operator = call.operator();
   216	    if (operator == Operators.NOT) {
   217	      return quantifiedExpression((Call) call.arguments().get(0), root, !expected);
   218	    }
   219	
   220	    if (operator == Operators.AND || operator == Operators.OR) {
   221	      List<BsonValue> values = call.arguments().stream()
   222	          .map(argument -> quantifiedExpression((Call) argument, root, expected))
   223	          .collect(Collectors.toList());
   224	      boolean useAnd = expected == (operator == Operators.AND);
   225	      return logical(useAnd ? "$and" : "$or", values);
   226	    }
   227	
   228	    if (operator == IterableOperators.ANY || operator == IterableOperators.ALL || operator == IterableOperators.NONE) {
   229	      Path path = reconstructFullPath((Path) call.arguments().get(0));
   230	      String suffix = path == null ? "" : "." + fieldName(path);
   231	      String variable = "element" + Math.abs(call.hashCode());
   232	      BsonValue input = new BsonString(root + suffix);
   233	      return logical("$and", java.util.Arrays.asList(
   234	          expression("$isArray", input),
   235	          buildQuantifierExpression(operator, input,
   236	              (Call) call.arguments().get(1), variable, expected)));
   237	    }
   238	
   239	    Path path = reconstructFullPath((Path) call.arguments().get(0));
   240	    BsonValue value = new BsonString(path == null ? root : root + "." + fieldName(path));
   241	    return quantifiedLeaf(call, value, expected);
   242	  }
   243	
   244	  private BsonValue quantifiedLeaf(Call call, BsonValue value, boolean expected) {
   245	    Operator operator = call.operator();
   246	    BsonValue present = expression("$ne", expression("$ifNull", value, BsonNull.VALUE), BsonNull.VALUE);
   247	    if (operator == OptionalOperators.IS_ABSENT) {
   248	      return expected ? expression("$not", present) : present;
   249	    } else if (operator == OptionalOperators.IS_PRESENT) {
   250	      return expected ? present : expression("$not", present);
   251	    }
   252	
   253	    BsonValue result;
   254	    if (operator == Operators.EQUAL || operator == Operators.NOT_EQUAL) {
   255	      boolean equal = (operator == Operators.EQUAL) == expected;
   256	      result = expression(equal ? "$eq" : "$ne", value, constant(call.arguments().get(1)));
   257	    } else if (operator == Operators.IN || operator == Operators.NOT_IN) {
   258	      result = expression("$in", value, constant(call.arguments().get(1)));
   259	      if ((operator == Operators.NOT_IN) == expected) {
   260	        result = expression("$not", result);
    45	  }
